int mbedtls_ssl_get_psk_hint(mbedtls_ssl_context *ssl, unsigned char **p, unsigned char *end) {
    size_t len = 0;

    if (ssl == NULL || p == NULL || *p > end) {
        return MBEDTLS_ERR_SSL_BAD_INPUT_DATA;
    }

    if ((end - *p) < 2) {
        return MBEDTLS_ERR_SSL_TRUNCATED_HELLO; // Not enough data for length field
    }

    len = (*p)[0] << 8 | (*p)[1];
    *p += 2;

    if (len > (size_t)(end - *p)) {
        return MBEDTLS_ERR_SSL_TRUNCATED_HELLO; // Not enough data for the full hint
    }

    // Skip the hint data
    *p += len;

    return 0;
}
